PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT (
    (COUNT(?dragonSpeakingBoth) * 100.0 / COUNT(?dragon)) AS ?percentage
) AS ?result
WHERE {
    ?dragon a <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Beast>.
    FILTER regex(str(?dragon), "Dragon", "i").

    # Count all dragons
    {
        ?dragon a <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Beast>.
        FILTER regex(str(?dragon), "Dragon", "i").
    }

    # Count dragons speaking both languages
    {
        ?dragon a <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Beast>.
        FILTER regex(str(?dragon), "Dragon", "i").
        ?dragon <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#hasLanguages> :DraconicL.
        ?dragon <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#hasLanguages> :CommonL.
    }
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT 
  (AVG(?dragonLangCount) AS ?avgDragonLanguages) 
  (AVG(?demonLangCount) AS ?avgDemonLanguages)
WHERE {
  {
    ?dragon a <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Beast> ;
            <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#hasAlignment> ?dragonAlignment .
    FILTER(?dragonAlignment = "Dragon") # Assuming "Dragon" is the alignment or category for dragons
    ?dragon <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#hasLanguages> ?dragonLang .
    BIND(COUNT(?dragonLang) AS ?dragonLangCount)
  }
  UNION
  {
    ?demon a <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Beast> ;
           <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#hasAlignment> ?demonAlignment .
    FILTER(?demonAlignment = "Demon") # Assuming "Demon" is the alignment or category for demons
    ?demon <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#hasLanguages> ?demonLang .
    BIND(COUNT(?demonLang) AS ?demonLangCount)
  }
}
GROUP BY ?dragonAlignment ?demonAlignment

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT DISTINCT ?beastName
WHERE {
  ?beast <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#hasName> ?beastName .
  ?beast <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#hasLanguages> ?language .
  ?language <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#spokenBy> ?beast .
  FILTER (?language IN ("Common", "Undercommon"))
  {
    SELECT ?beast
    WHERE {
      ?beast <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#hasLanguages> ?lang .
      FILTER (?lang IN ("Common", "Undercommon"))
    }
    GROUP BY ?beast
    HAVING (COUNT(DISTINCT ?lang) = 2)
  }
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT (COUNT(?beast) AS ?count)
