SELECT (COUNT(?skeletonTrueNeutral) * 100 / COUNT(?skeleton)) AS ?skeletonTrueNeutralPercentage,
       (COUNT(?zombieTrueNeutral) * 100 / COUNT(?zombie)) AS ?zombieTrueNeutralPercentage,
       (COUNT(?skeletonTrueNeutral) * 100 / COUNT(?skeleton)) > (COUNT(?zombieTrueNeutral) * 100 / COUNT(?zombie)) AS ?result
