PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT (
    (COUNT(?chaoticWolf) * 100.0 / COUNT(?wolf)) AS ?percentage
) AS ?chaoticPercentage
WHERE {
    ?wolf a <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Beast> ;
